    def __iinterface_refs__(self) -> int:
        r""" Reference counter of the native objects."""
        return _pymdlsdk.IDatabase___iinterface_refs__(self)

    def __iinterface_ptr_as_uint64__(self, retain: bool=False) -> int:
        r"""
        Get the native pointer as uint64. E.g. for comparison.

        :type retain: boolean, optional
        :param retain:   If true, the native refcount is increased.
                            Do not use this unless for interop with native code.

        :rtype: int
        :return: The native point as uint64.
        """
        return _pymdlsdk.IDatabase___iinterface_ptr_as_uint64__(self, retain)

    @staticmethod
    def IID() -> "Uuid":
        r"""
        Declares the interface ID (IID) of this interface.

        A local type in each interface type, which is distinct and unique for each interface. The
        type has a default constructor and the constructed value represents the universally unique
        identifier (UUID) for this interface. The local type is readily convertible to a
        #mi::base::Uuid.
        """
        return _pymdlsdk.IDatabase_IID()

    @staticmethod
    def _get_interface(iface: "IInterface") -> "IDatabase":
        r"""
        this creates a static function at the target interface class to convert an interface pointer
        into an object of the own class, e.g.:
        [python] cfg = pymdlsdk.IMdl_configuration.get_interface(iinterface)
        """
        return _pymdlsdk.IDatabase__get_interface(iface)

    def get_interface(self, type):
        r"""
        Acquires an interfaces of a given other ``type``.
        If the type hierarchy of the calling object does not contain the specified ``type``,
        an invalid interface is returned.
        """
        typed_interface = type._get_interface(self)
        return typed_interface



    class Garbage_collection_priority(Enum) :
        r"""Priorities for synchronous garbage collection runs."""

        PRIORITY_LOW = _pymdlsdk._IDatabase_PRIORITY_LOW
        r"""
        Low priority for synchronous garbage collection runs.Use this priority if the
        performance of other concurrent DB operations is more important than a fast synchronous
        garbage collection.
        """
        PRIORITY_MEDIUM = _pymdlsdk._IDatabase_PRIORITY_MEDIUM
        r"""
        Medium priority for synchronous garbage collection runs.This priority attempts to
        maintain a balance between the synchronous garbage collection and other concurrent DB
        operations.
        """
        PRIORITY_HIGH = _pymdlsdk._IDatabase_PRIORITY_HIGH
        r"""
        High priority for synchronous garbage collection runs.Other concurrent DB operations
        will experience a large performance drop.Therefore, this priority should not be used
        in multi - user settings.
        """
        PRIORITY_FORCE_32_BIT = _pymdlsdk._IDatabase_PRIORITY_FORCE_32_BIT


    def get_global_scope(self) -> "IScope":
        r"""
        Returns the global scope which is the root of a tree of scopes

        :rtype: :py:class:`IScope`
        :return: The global scope which is guaranteed to exist after startup of the
                     system.
        """
        return _pymdlsdk.IDatabase_get_global_scope(self)

    def create_scope(self, parent: "IScope", privacy_level: int=0, temp: bool=False) -> "IScope":
        r"""
        Creates a new unnamed scope.

        Notes: A scope continues to exist if the pointer returned by this method is released. Use
              #remove_scope() to remove a scope.

        :type parent: :py:class:`IScope`
        :param parent:         The parent scope for this scope. The value ``nullptr`` represents the
                                  global scope.
        :type privacy_level: mi::Uint8, optional
        :param privacy_level:  The privacy level of the scope, which must be higher than the privacy
                                  level of the parent scope. The privacy level of the global scope is 0
                                  (and the global scope is the only scope with privacy level 0). The
                                  default value of 0 indicates the privacy level of the parent scope
                                  plus 1.
        :type temp: boolean, optional
        :param temp:       If not: MDL_SDK_API { A flag indicating whether the scope is temporary.
                              A non-temporary scope needs to be explicitly removed via
                              #remove_scope(). A temporary scope is automatically removed when the
                              host creating it leaves the cluster. }Else: Unused.  {}
        :rtype: :py:class:`IScope`
        :return: The created scope, or ``nullptr`` in case of errors.
        """
        return _pymdlsdk.IDatabase_create_scope(self, parent, privacy_level, temp)

    def create_or_get_named_scope(self, name: str, parent: "IScope"=None, privacy_level: int=0) -> "IScope":
        r"""
        Creates a new named scope (or retrieves an existing one).

        :type name: string
        :param name:           The name of the new scope. If there is no scope with that name, it
                                  will be created with the given parent scope and privacy level.
                                  Otherwise, if the given parent scope and privacy level match the
                                  properties of an existing scope with that name, then that scope will
                                  be returned. If there is a mismatch, neither a scope will be created
                                  nor returned, and the method returns ``nullptr``.
        :type parent: :py:class:`IScope`, optional
        :param parent:         The parent scope for this scope. The value ``nullptr`` represents the
                                  global scope.
        :type privacy_level: mi::Uint8, optional
        :param privacy_level:  The privacy level of the scope, which must be higher than the privacy
                                  level of the parent scope. The privacy level of the global scope is 0
                                  (and the global scope is the only scope with privacy level 0). The
                                  default value of 0 indicates the privacy level of the parent scope
                                  plus 1.
        :rtype: :py:class:`IScope`
        :return: The created scope, or ``nullptr`` in case of errors.
        """
        return _pymdlsdk.IDatabase_create_or_get_named_scope(self, name, parent, privacy_level)

    def get_scope(self, id: str) -> "IScope":
        r"""
        Looks up a scope by ID.

        :type id: string
        :param id:             The ID of the scope as returned by #mi::neuraylib::IScope::get_id().
        :rtype: :py:class:`IScope`
        :return: The found scope or ``nullptr`` if no such scope exists.
        """
        return _pymdlsdk.IDatabase_get_scope(self, id)

    def get_named_scope(self, name: str) -> "IScope":
        r"""
        Looks up a scope by name.

        :type name: string
        :param name:           The name of the scope
        :rtype: :py:class:`IScope`
        :return: The found scope or ``nullptr`` if no such scope exists.
        """
        return _pymdlsdk.IDatabase_get_named_scope(self, name)

    def remove_scope(self, id: str) -> int:
        r"""
        Removes a scope with the specified ID.

        Note that scopes are reference counted. The actual removal will not happen before all
        elements referencing the scope have been released, e.g., child scopes, transactions,
        database elements, including handles to the scope itself. Even when all these conditions
        are met, scope removal might actually happen at a later point in time, depending on the
        timing of past and current transactions, even in unrelated scopes.

        It is not possible to remove the global scope.

        :type id: string
        :param id:             The ID of the scope as returned by #mi::neuraylib::IScope::get_id().
        :rtype: int
        :return: 0, in case of success, -1 in case of failure.
        """
        return _pymdlsdk.IDatabase_remove_scope(self, id)

    def garbage_collection(self, *args) -> None:
        r"""
        Triggers a synchronous garbage collection run.

        The method sweeps through the entire database and removes all database elements which have
        been marked for removal and are no longer referenced. Note that it is not possible to remove
        database elements if there are open transactions in which such an element is still
        referenced.

        To mark an element for removal use If not: DICE_API { #mi::neuraylib::ITransaction::remove().
        }Else: #mi::neuraylib::IDice_transaction::remove() or {
        #mi::neuraylib::IDice_transaction::store_for_reference_counting(). }

        :type priority: int, optional
        :param priority:   The intended priority of the synchronous garbage collection run.
                          If: MDL_SDK_API { The MDL SDK does not support different priorities, and
                          the synchronous garbage collection always runs at highest priority.
                          }
        """

        argc: int = len(args)
        if argc == 0:
            args = (IDatabase.Garbage_collection_priority.PRIORITY_LOW.value, )
        if argc == 1:
            args = (args[0].value, ) # unwrap python enum and pass the integer value


        return _pymdlsdk.IDatabase_garbage_collection(self, *args)


    def compare_iid(self, iid: "Uuid") -> bool:
        r"""
        Compares the interface ID ``iid`` against the interface ID of this interface and of its
        ancestors.

        :rtype: boolean
        :return: ``true`` if ``iid`` == ``IID()`` or is equal to one of the interface IDs of
            its ancestors, and ``false`` otherwise.
        """
        return _pymdlsdk.IDatabase_compare_iid(self, iid)

    def get_iid(self) -> "Uuid":
        r""" Returns the interface ID of the most derived interface."""
        return _pymdlsdk.IDatabase_get_iid(self)

