        # _pymdlsdk.IFunction_definition_swiginit(self, _pymdlsdk.new_IFunction_definition(*args))
    __swig_destroy__ = _pymdlsdk.delete_IFunction_definition

    def is_valid_interface(self) -> bool:
        r"""
        Checks if a given neuray object is valid.
        If false, the object can not be used further and object should be treated as if it was None.
        """
        return _pymdlsdk.IFunction_definition_is_valid_interface(self)

    def __enter__(self) -> "IFunction_definition":
        r""" Enter function for `with` blocks"""
        return _pymdlsdk.IFunction_definition___enter__(self)

    def __exit__(self, exc_type, exc_value, exc_traceback) -> bool:
        r""" Exit function for `with` blocks"""
        return _pymdlsdk.IFunction_definition___exit__(self, exc_type, exc_value, exc_traceback)

    def release(self) -> None:
        r"""
        release-function exposed to python.
        decrements the ref count internally and makes the python proxy invalid (holds nullptr).
        """
        return _pymdlsdk.IFunction_definition_release(self)

    def __iinterface_refs__(self) -> int:
        r""" Reference counter of the native objects."""
        return _pymdlsdk.IFunction_definition___iinterface_refs__(self)

    def __iinterface_ptr_as_uint64__(self, retain: bool=False) -> int:
        r"""
        Get the native pointer as uint64. E.g. for comparison.

        :type retain: boolean, optional
        :param retain:   If true, the native refcount is increased.
                            Do not use this unless for interop with native code.

        :rtype: int
        :return: The native point as uint64.
        """
        return _pymdlsdk.IFunction_definition___iinterface_ptr_as_uint64__(self, retain)

    @staticmethod
    def IID() -> "Uuid":
        r"""
        Declares the interface ID (IID) of this interface.

        A local type in each interface type, which is distinct and unique for each interface. The
        type has a default constructor and the constructed value represents the universally unique
        identifier (UUID) for this interface. The local type is readily convertible to a
        #mi::base::Uuid.
        """
        return _pymdlsdk.IFunction_definition_IID()

    @staticmethod
    def _get_interface(iface: "IInterface") -> "IFunction_definition":
        r"""
        this creates a static function at the target interface class to convert an interface pointer
        into an object of the own class, e.g.:
        [python] cfg = pymdlsdk.IMdl_configuration.get_interface(iinterface)
        """
        return _pymdlsdk.IFunction_definition__get_interface(iface)

    def get_interface(self, type):
        r"""
        Acquires an interfaces of a given other ``type``.
        If the type hierarchy of the calling object does not contain the specified ``type``,
        an invalid interface is returned.
        """
        typed_interface = type._get_interface(self)
        return typed_interface


    def get_mdl_version(self) -> tuple[Mdl_version, Mdl_version]:
        r"""
        Returns the MDL version when this function definition was added and removed.
        :rtype: (Mdl_version, Mdl_version)
        :return: A tuple of (since, removed) versions.
                 since     The MDL version in which this function definition was added. If the
                           function definition does not belong to the standard library, the
                           MDL version of the corresponding module is returned.
                 removed   The MDL version in which this function definition was removed, or
                           mi::neuraylib::MDL_VERSION_INVALID if the function has not been
                           removed so far or does not belong to the standard library.
        """
        since, remove = self._get_mdl_version()
        return (Mdl_version(since), Mdl_version(remove))



